const fs = require('fs');
const path = require('path');

const FORCE = process.argv.includes('--force');
const ARQUIVOS = {
".env.local.exemplo": "",
".gitignore": "bm9kZV9tb2R1bGVzCi5uZXh0Cm91dAouZW52LmxvY2FsCi5lbnYqLmxvY2FsCi52ZXJjZWwKLkRTX1N0b3JlCioubG9nCg==",
"README.md": "",
"components/Dashboard.jsx": "",
"components/MedicaoSemanal.jsx": "",
"components/Lancamentos.jsx": "",
"components/PrevisaoDesembolso.jsx": "",
"components/Desbloqueio.jsx": "",
"components/MapaPavimentos.jsx": "",
"components/FisicoPorAtividade.jsx": "",
"components/DiarioOcorrencias.jsx": "",
"lib/constants.js": "",
"lib/supabase.js": "",
"next.config.js": "LyoqIEB0eXBlIHtpbXBvcnQoJ25leHQnKS5OZXh0Q29uZmlnfSAqLwptb2R1bGUuZXhwb3J0cyA9IHsgcmVhY3RTdHJpY3RNb2RlOiB0cnVlIH0K",
"package.json": "",
"pages/_app.js": "aW1wb3J0ICcuLi9zdHlsZXMvZ2xvYmFscy5jc3MnCgpleHBvcnQgZGVmYXVsdCBmdW5jdGlvbiBBcHAoeyBDb21wb25lbnQsIHBhZ2VQcm9wcyB9KSB7CiAgcmV0dXJuIDxDb21wb25lbnQgey4uLnBhZ2VQcm9wc30gLz4KfQo=",
"pages/api/dashboard-integrado.js": "",
"pages/api/medicao.js": "",
"pages/api/lancamentos.js": "",
"pages/api/indiretos.js": "",
"pages/api/avanco.js": "",
"pages/api/auth.js": "",
"pages/api/ocorrencias.js": "",
"pages/index.js": "",
"pages/custos-diretos.js": "",
"pages/custos-indiretos.js": "",
"pages/avanco-fisico.js": "",
"public/dados.json": "",
"styles/globals.css": ""
};

let criados = 0, iguais = 0;
const conflitos = [];

for (const [rel, b64] of Object.entries(ARQUIVOS)) {
  const destino = path.join(process.cwd(), rel);
  const conteudo = Buffer.from(b64, 'base64');
  const dir = path.dirname(destino);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

  if (fs.existsSync(destino)) {
    const atual = fs.readFileSync(destino);
    if (atual.equals(conteudo)) { iguais++; continue; }
    if (!FORCE) { conflitos.push(rel); continue; }
  }
  fs.writeFileSync(destino, conteudo);
  console.log('  criado  ' + rel);
  criados++;
}

console.log('');
console.log('Arquivos criados: ' + criados + '  |  ja identicos: ' + iguais);

if (conflitos.length) {
  console.log('');
  console.log('ATENCAO - estes arquivos JA EXISTEM com conteudo diferente e NAO foram tocados:');
  conflitos.forEach(c => console.log('   ' + c));
  console.log('');
  console.log('Confira o que ha neles antes de decidir. Para sobrescrever tudo:');
  console.log('   node setup-sirius60-v39.js --force');
} else {
  console.log('');
  console.log('PROXIMOS PASSOS');
  console.log('  1) copy .env.local.exemplo .env.local');
  console.log('  2) abra .env.local e cole a URL e a chave anon do Supabase');
  console.log('  3) npm install');
  console.log('  4) npm run dev      -> http://localhost:3000');
}
